def _read_plan() -> str:
    plan = HANDOFF / "plan.md"
    for _ in range(50):
        if plan.exists():
            return plan.read_text(encoding="utf-8", errors="replace")
        time.sleep(0.1)
    return ""


def _delegation_id(plan: str) -> str:
    match = re.search(
        r"delegation_id\s*[:=]\s*[\"'`]?([A-Za-z0-9._-]+)", plan, re.IGNORECASE
    )
    return match.group(1) if match else ""


def _delegated_actor(plan: str, actors: dict) -> str:
    match = re.search(
        r"delegated_actor\s*[:=]\s*[\"'`]?([A-Za-z0-9_-]+)", plan, re.IGNORECASE
    )
    if match and match.group(1) in actors:
        return match.group(1)
    # The upstream plan remains authoritative even when its header is reflowed
    # by the stage writer; fall back to the delegation issuer.
    for stage in ("analyst", "operator", "auditor"):
        if stage in actors:
            return stage
    return next(iter(actors))
